my $in = $seq{input};
my $out = $seq{output};
my $egfp = $seq{egfp};
my $flag = $seq{flag};
my $snap = $seq{snap};

# Structure of output (circular):
# [0:214] = input[0:214] (common prefix, ends with ATG of egfp)
# [214:924] = egfp[4:-3] (egfp without ATG and without stop)
# [924:1008] = flag[3:-3] (flag without ATG and without stop)
# [1008:1551] = snap[3:-3] (snap without ATG and without stop)
# [1551:3591] = input[687:2727] (common suffix)

