print "output suffix len: ", length($out_suffix), "\n";
print "match: ", ($in_suffix eq $out_suffix ? "YES" : "NO"), "\n\n";

# So the input has a "stuffer" region [214:687] that is replaced
# input[214:687] = the stuffer (473 bp)
my $stuffer = substr($in, 214, 687-214);
