perl -e '
my %seq; my $name;
open(my $fh, "<", "sequences.fasta") or die;
while (<$fh>) {
    chomp;
    if (/^>(\S+)/) { $name = $1; $seq{$name} = ""; }
    elsif ($name) { $seq{$name} .= $_; }
}
close($fh);
my $in = $seq{input};
my $out = $seq{output};
my $egfp = $seq{egfp};
my $flag = $seq{flag};
my $snap = $seq{snap};

# Verify structure:
# output = input[0:214] + egfp[4:-3] + flag[3:-3] + snap[3:-3] + input[687:]
# Junctions (in output coordinates):
# J1: backbone -> egfp at position 214
# J2: egfp -> flag at position 214+710 = 924
# J3: flag -> snap at position 924+84 = 1008
# J4: snap -> backbone at position 1008+543 = 1551

my @junctions = (214, 924, 1008, 1551);
my @names = ("J1: backbone->egfp", "J2: egfp->flag", "J3: flag->snap", "J4: snap->backbone");

for my $i (0..3) {
    my $j = $junctions[$i];
    print "$names[$i] at output position $j\n";
    print "  Left (output[$j-10..$j]):  ", substr($out, $j-10, 10), "\n";
    print "  Right(output[$j..$j+10]): ", substr($out, $j, 10), "\n";
    # Show 4-nt windows spanning the junction
    for my $offset (-3..3) {
        my $start = $j + $offset;
        my $oh = substr($out, $start, 4);
        my $left_nt = $j - $start;
        my $right_nt = 4 - $left_nt;
        printf "  overhang output[%d:%d] = %s  (%d from left, %d from right)\n", $start, $start+4, $oh, $left_nt, $right_nt;
    }
    print "\n";
}

# Also verify the circular junction (input end -> input start)
print "J5 (circular: backbone end -> backbone start):\n";
print "  input end:   ...", substr($in, -10), "\n";
print "  input start: ", substr($in, 0, 10), "...\n";
print "  output end:  ...", substr($out, -10), "\n";
