# Check for BsaI sites (GGTCTC and reverse complement GAGACC) in all sequences
perl -e '
my %seq; my $name;
open(my $fh, "<", "sequences.fasta") or die;
while (<$fh>) {
    chomp;
    if (/^>(\S+)/) { $name = $1; $seq{$name} = ""; }
