    my @fwd = ();
    my @rev = ();
    while ($s =~ /GGTCTC/gi) { push @fwd, pos($s) - 6; }
    while ($s =~ /GAGACC/gi) { push @rev, pos($s) - 6; }
    print "$n: GGTCTC sites at @fwd, GAGACC sites at @rev\n";
}

# Also check the backbone fragment (input with stuffer removed)
# backbone = input[687:2727] + input[0:214]
my $backbone = substr($seq{input}, 687) . substr($seq{input}, 0, 214);
my @fwd = ();
my @rev = ();
while ($backbone =~ /GGTCTC/gi) { push @fwd, pos($backbone) - 6; }
while ($backbone =~ /GAGACC/gi) { push @rev, pos($backbone) - 6; }
print "backbone: GGTCTC sites at @fwd, GAGACC sites at @rev\n";
'

# Let me verify the BsaI cut mechanism and check NEB's requirements
# BsaI-HF v2: GGTCTC(1/5) - cuts 1nt 3' on top, 5nt 3' on bottom, leaving 4nt 5' overhang
# 
# The primer structure for Golden Gate:
# Forward: 5'-GGTCTC N [4nt overhang] [annealing region]-3'
# Reverse: 5'-GGTCTC N [rc(4nt overhang)] [annealing region]-3'
#
# After BsaI digestion, the fragment has 4nt 5' overhangs matching the output sequence.
#
# Let me now choose overhangs at each junction.
# I need 4 unique, non-palindromic overhangs, no two being reverse complements.

# Junction options:
# J1 (pos 214): tgag, gagc, agca, gcaa  (and more)
# J2 (pos 924): aaag, aagg, aggt, ggta  (and more)
# J3 (pos 1008): tcag, caga, agac, gaca  (and more)
# J4 (pos 1551): ggtt, gtta, ttaa, taat  (and more)

# Let me check reverse complements:
perl -e '
sub rc { my $s = reverse(shift); $s =~ tr/ACGT/TGCA/; return $s; }
my @candidates = (
    ["J1", ["tgag","gagc","agca","gcaa"]],
    ["J2", ["aaag","aagg","aggt","ggta"]],
    ["J3", ["tcag","caga","agac","gaca"]],
    ["J4", ["ggtt","gtta","ttaa","taat"]],
);
for my $j (@candidates) {
    print "$j->[0]:\n";
    for my $o (@{$j->[1]}) {
        my $r = rc($o);
        my $pal = ($o eq $r) ? "PALINDROME" : "";
        printf "  %s -> rc=%s  %s\n", $o, $r, $pal;
    }
}
'

perl -e '
sub rc { 
