print "rc(caga) = ", rc("caga"), "\n";
print "rc(gtta) = ", rc("gtta"), "\n";
print "rc(gagc) = ", rc("gagc"), "\n\n";

# Now check all candidate overhangs at each junction
# J1 (pos 214): options with 2-2 split: output[212:216]
# J2 (pos 924): output[922:926]
# J3 (pos 1008): output[1006:1010]
# J4 (pos 1551): output[1549:1553]

my %seq; my $name;
open(my $fh, "<", "sequences.fasta") or die;
while (<$fh>) {
